<form method="post" class="grid gap-4 rounded-3xl border border-slate-200 bg-white p-6 md:grid-cols-2"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label class="field">WordPress URL<input name="store_url" placeholder="https://example.com"></label><label class="field">Consumer Key (REST API)<input name="consumer_key"></label><label class="field">Consumer Secret (REST API)<input name="consumer_secret"></label><label class="field">Import Limit<input type="number" name="limit" value="12"></label><label class="field">Vendor Owner<select name="vendor_id"><?php foreach ($vendors as $vendor): ?><option value="<?= (int)$vendor['id'] ?>"><?= e($vendor['store_name']) ?></option><?php endforeach; ?></select></label><label class="field">Category<select name="category_id"><?php foreach ($categories as $category): ?><option value="<?= (int)$category['id'] ?>"><?= e($category['name']) ?></option><?php endforeach; ?></select></label><button class="rounded-2xl bg-emerald-600 p-4 font-black text-white md:col-span-2">Import from WordPress REST API</button></form><div class="mt-6 rounded-3xl border border-slate-200 bg-white p-6"><h2 class="text-xl font-black">Supported Import Methods</h2><ul class="mt-3 list-disc space-y-1 pl-5 text-slate-600"><li>WordPress XML (planned)</li><li>WordPress REST API (active)</li><li>CSV import (planned)</li><li>Bulk import queue (planned)</li></ul></div><div class="mt-6 overflow-x-auto rounded-3xl border border-slate-200 bg-white"><table class="admin-table"><tr><th>Source</th><th>Count</th><th>Status</th><th>Message</th></tr><?php foreach ($imports as $import): ?><tr><td><?= e($import['store_url']) ?></td><td><?= (int)$import['imported_count'] ?></td><td><?= e($import['status']) ?></td><td><?= e($import['message']) ?></td></tr><?php endforeach; ?></table></div>
